CREATE TABLE t3928(a INTEGER PRIMARY KEY AUTOINCREMENT, b); INSERT INTO t3928(a,b) VALUES(1,456),(14,'before-int-456'),(15,'after-int-456'); CREATE TRIGGER t3928r3 BEFORE UPDATE ON t3928 WHEN typeof(new.b)='integer' BEGIN INSERT INTO t3928(b) VALUES('before-int-' || new.b); END; CREATE TRIGGER t3928r4 AFTER UPDATE ON t3928 WHEN typeof(new.b)='integer' BEGIN INSERT INTO t3928(b) VALUES('after-int-' || new.b); END;